import React from "react";
import "./ProductDisplay.css";

const ProductDisplay = ({ product }) => {
  return (
    <div className="product-display">
      <div className="product-display-left">
        <div className="product-thumbnails">
          {product.images?.map((img, i) => (
            <img key={i} src={img} alt={`${product.name}-${i}`} />
          ))}
        </div>
        <div className="product-main-image">
          <img src={product.image} alt={product.name} />
        </div>
      </div>

      <div className="product-display-right">
        <h2 className="product-name">{product.name}</h2>
        <p className="product-category">{product.category}</p>

        <div className="product-stars">
          {Array.from({ length: 5 }).map((_, i) => (
            <span key={i} className={i < product.star ? "filled" : ""}>★</span>
          ))}
          <span className="review-count">({product.reviews} reviews)</span>
        </div>

        <div className="product-prices">
          <span className="new-price">Rs. {product.new_price.toFixed(2)}</span>
          <span className="old-price">Rs. {product.old_price.toFixed(2)}</span>
        </div>

        <p className="product-description">{product.description}</p>
      </div>
    </div>
  );
};

export default ProductDisplay;
